using System;using System.IO;using System.Collections.Generic;using System.Xml;using UnityEngine;
public class ConsoleCmdBatchOne:ConsoleCmdAbstract {
 public override string[] getCommands(){return new[]{"batchoneverify"};}
 public override string getDescription(){return "Validate Batch 01 on the isolated server.";}
 static int count; static void Check(bool ok,string text){count++;if(!ok)throw new Exception(text);}
 public override void Execute(List<string> args,CommandSenderInfo sender){EntityPlayer p=null;try {
  count=0;p=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),Vector3.zero) as EntityPlayer;p.world=GameManager.Instance.World;p.Progression.Level=1;
  Delve.CharacterProgression.Set(p,"delvePracticeCarpentry",0);
  foreach(string name in new[]{"armorPrimitiveHelmet","armorPrimitiveOutfit","armorPrimitiveGloves","armorPrimitiveBoots"}){
   var r=CraftingManager.GetRecipe(name);Check(r!=null,name+" recipe");Check(r.craftingArea==""||r.craftingArea==null,name+" inventory station");Check(r.IsUnlocked(p),name+" fresh player unlocked");Check(r.CanCraft(new List<ItemStack>(r.ingredients),p,-1),name+" fresh player can craft");Check(!r.CanCraft(new List<ItemStack>(),p,-1),name+" still needs ingredients");Check(ItemClass.GetItemClass(name).UnlockedBy.Length==0,name+" has no unlock gate");
  }
  // Execute the exact repeatedly failing UI binding, including other empty unlock entries.
  int blank=0,valid=0;foreach(var item in ItemClass.list){if(item==null)continue;bool empty=Delve.RecipeUnlockPresentation.Blank(item.Properties);if(empty){for(int i=0;i<100;i++)Check(item.UnlockedBy.Length==0,item.GetItemName()+" empty unlock list");blank++;}else if(!Delve.RecipeUnlockPresentation.Primitive(item.GetItemName())){foreach(var entry in item.UnlockedBy){Check(entry.GetName()!=null,item.GetItemName()+" valid unlock binding");valid++;}}}
  Check(blank>10&&valid>10,"both blank and valid unlocks covered");Check(ItemClass.GetItemClass("armorDelveMediumBoots").UnlockedBy.Length==0,"Border Leather Boots no invalid row");
  var doc=new XmlDocument();doc.Load(Path.Combine(ModManager.GetMod("BatchOneProbe",true).Path,"vehicles.xml"));int vehicles=0;
  foreach(XmlElement e in doc.SelectNodes("/vehicles/vehicle")){var b=Block.GetBlockByName(e.GetAttribute("name"));Check(b!=null,e.GetAttribute("name")+" retains ID");Check(b.Properties.Values["Model"].EndsWith("?delveWagon"+e.GetAttribute("stage")),b.GetBlockName()+" stage");string d;bool has=b.Properties.Values.TryGetValue("DowngradeBlock",out d);Check((has?d:"")==e.GetAttribute("downgrade"),b.GetBlockName()+" downgrade preserved");Check(!b.Properties.Values.ContainsKey("ParticleOnDeath"),b.GetBlockName()+" no car debris");vehicles++;}
  Check(vehicles==340,"complete vehicle coverage");
  var resin=ItemClass.GetItemClass("resourceScrapPolymers");Check(Localization.Get("resourceScrapPolymers")=="Crafting Resin","localized resin");Check(resin.Properties.Values["CustomIcon"]=="delveCraftingResin","resin icon");Check(resin.Properties.Values["Stacknumber"]=="1000","resin stack retained");
  string output=Path.Combine(ModManager.GetMod("BatchOneProbe",true).Path,"Evidence");Directory.CreateDirectory(output);
  foreach(string id in new[]{"delveWagon0","delveWagon1","delveWagon2","delveCraftingResin"}){
   var prefab=DataLoader.LoadAsset<GameObject>("#@modfolder(ZZZDelveBatch01):Resources/batchone.unity3d?"+id,true);Check(prefab!=null,id+" loads in game");Check(prefab.GetComponentsInChildren<Renderer>(true).Length>0,id+" renderers");Check(prefab.GetComponentsInChildren<Collider>(true).Length>0,id+" collider");
   if(SystemInfo.graphicsDeviceType!=UnityEngine.Rendering.GraphicsDeviceType.Null)Capture(prefab,id,output);
  }
  SdtdConsole.Instance.Output("[BatchOne] PASS "+count+" checks: level-1 zero-practice primitive crafting, "+blank+" blank unlock items repeatedly bound, "+valid+" valid unlocks, "+vehicles+" vehicle stages/downgrades, resin identity/stack/icon and game-loaded asset colliders/renders.");
 }catch(Exception ex){SdtdConsole.Instance.Output("[BatchOne] FAIL "+ex);}finally{if(p!=null)UnityEngine.Object.Destroy(p.gameObject);}}
 static void Capture(GameObject prefab,string id,string output){var o=UnityEngine.Object.Instantiate(prefab);foreach(var t in o.GetComponentsInChildren<Transform>(true))t.gameObject.layer=30;var bounds=new Bounds();bool first=true;foreach(var r in o.GetComponentsInChildren<Renderer>()){Check(r.sharedMaterial!=null&&r.sharedMaterial.shader!=null,id+" material");if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}Check(bounds.size.magnitude>.1f&&bounds.size.magnitude<8,id+" sane bounds");var co=new GameObject("BatchCamera");var c=co.AddComponent<Camera>();c.enabled=false;c.cullingMask=1<<30;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.12f,.15f,.18f);c.orthographic=true;c.orthographicSize=id.StartsWith("delveWagon")?3:.23f;c.farClipPlane=30;c.transform.position=bounds.center+new Vector3(6,4,7);c.transform.LookAt(bounds.center);var lamp=new GameObject("BatchLight");var light=lamp.AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.4f;light.cullingMask=1<<30;lamp.transform.rotation=Quaternion.Euler(40,-35,0);var rt=new RenderTexture(512,512,24);c.targetTexture=rt;c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(512,512,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,512,512),0,0);image.Apply();RenderTexture.active=old;File.WriteAllBytes(Path.Combine(output,id+".png"),image.EncodeToPNG());c.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(image);UnityEngine.Object.Destroy(co);UnityEngine.Object.Destroy(lamp);o.SetActive(false);lamp.SetActive(false);UnityEngine.Object.Destroy(o);}
}

